insert into MST_BOND_CREDIT_RATING(O_CODE, GRADE_ORG_ID, GRADE_DATE, O_TYPE, SHORT_LONG_TERM, GRADE_RESULT, INPUT_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, IS_RECOMMAND, ISSUER_RATE_TYPE, NOTICE_DATE, GRADE_EXPECTATION, DIRECTION_CHANGE) select O_CODE, GRADE_ORG_ID, GRADE_DATE, O_TYPE, SHORT_LONG_TERM, GRADE_RESULT, INPUT_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, IS_RECOMMAND, ISSUER_RATE_TYPE, NOTICE_DATE, GRADE_EXPECTATION, DIRECTION_CHANGE from ( select TEMP.* from (
SELECT #{item.oCode,jdbcType=VARCHAR} O_CODE, #{item.gradeOrgId,jdbcType=VARCHAR} GRADE_ORG_ID, #{item.gradeDate,jdbcType=DATE} GRADE_DATE, #{item.oType,jdbcType=VARCHAR} O_TYPE, #{item.shortLongTerm,jdbcType=VARCHAR} SHORT_LONG_TERM, #{item.gradeResult,jdbcType=VARCHAR} GRADE_RESULT, #{item.inputType,jdbcType=VARCHAR} INPUT_TYPE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, NOW() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.isRecommand,jdbcType=VARCHAR} IS_RECOMMAND, #{item.issuerRateType,jdbcType=VARCHAR} ISSUER_RATE_TYPE, #{item.noticeDate,jdbcType=DATE} NOTICE_DATE, #{item.gradeExpectation,jdbcType=VARCHAR} GRADE_EXPECTATION, #{item.directionChange,jdbcType=VARCHAR} DIRECTION_CHANGE FROM DUAL
) TEMP where not exists (select 1 from MST_BOND_CREDIT_RATING CII where CII.O_CODE = TEMP.O_CODE and CII.GRADE_ORG_ID = TEMP.GRADE_ORG_ID and CII.GRADE_DATE = TEMP.GRADE_DATE and CII.O_TYPE = TEMP.O_TYPE) ) de ;
UPDATE MST_BOND_CREDIT_RATING as A, ( select SHORT_LONG_TERM, GRADE_RESULT, INPUT_TYPE, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, IS_RECOMMAND, ISSUER_RATE_TYPE, NOTICE_DATE, GRADE_EXPECTATION, DIRECTION_CHANGE from ( select TEMP.* from (
SELECT #{item.oCode,jdbcType=VARCHAR} O_CODE, #{item.gradeOrgId,jdbcType=VARCHAR} GRADE_ORG_ID, #{item.gradeDate,jdbcType=DATE} GRADE_DATE, #{item.oType,jdbcType=VARCHAR} O_TYPE, #{item.shortLongTerm,jdbcType=VARCHAR} SHORT_LONG_TERM, #{item.gradeResult,jdbcType=VARCHAR} GRADE_RESULT, #{item.inputType,jdbcType=VARCHAR} INPUT_TYPE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, NOW() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.isRecommand,jdbcType=VARCHAR} IS_RECOMMAND, #{item.issuerRateType,jdbcType=VARCHAR} ISSUER_RATE_TYPE, #{item.noticeDate,jdbcType=DATE} NOTICE_DATE, #{item.gradeExpectation,jdbcType=VARCHAR} GRADE_EXPECTATION, #{item.directionChange,jdbcType=VARCHAR} DIRECTION_CHANGE FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from MST_BOND_CREDIT_RATING CII where CII.O_CODE = TEMP.O_CODE and CII.GRADE_ORG_ID = TEMP.GRADE_ORG_ID and CII.GRADE_DATE = TEMP.GRADE_DATE and CII.O_TYPE = TEMP.O_TYPE);
